ALTER TABLE public.weddings ALTER COLUMN messages_auto_approve SET DEFAULT false;
CREATE OR REPLACE FUNCTION public.post_public_message(p_wedding_id uuid,p_name text,p_body text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n text:=trim(coalesce(p_name,'')); b text:=trim(coalesce(p_body,'')); BEGIN IF length(n)<2 OR length(n)>80 OR length(b)<3 OR length(b)>1000 THEN RAISE EXCEPTION 'Informe um nome de 2 a 80 caracteres e um recado de 3 a 1000 caracteres.'; END IF; IF NOT EXISTS(SELECT 1 FROM public.weddings WHERE id=p_wedding_id AND published AND approval_status='approved') THEN RAISE EXCEPTION 'Este site ainda não está liberado.'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(p_wedding_id::text||lower(n),0)); IF EXISTS(SELECT 1 FROM public.wedding_messages WHERE wedding_id=p_wedding_id AND (lower(author_name)=lower(n) OR (auth.uid() IS NOT NULL AND user_id=auth.uid())) AND created_at>now()-interval '1 minute') THEN RAISE EXCEPTION 'Aguarde um minuto antes de enviar outro recado.'; END IF; INSERT INTO public.wedding_messages(wedding_id,user_id,author_name,body,approved) VALUES(p_wedding_id,auth.uid(),n,b,false); END $$;
REVOKE ALL ON FUNCTION public.post_public_message(uuid,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.post_public_message(uuid,text,text) TO anon,authenticated,service_role;